// Graphite Neon: подписи нижнего меню (Analytics / Profile) только для этой темы
function syncGraphiteShell() {
  const on = document.body.classList.contains("theme-graphiteNeon");
  const apply = (el, key) => {
    if (!el || el.dataset.i18n === key) return;
    el.dataset.i18n = key;
    el.textContent = t(key);
    const btn = el.closest("button");
    if (btn) {
      btn.title = t(key);
      btn.setAttribute("aria-label", t(key));
    }
  };
  document
    .querySelectorAll(
      '#mainNav .nav-btn[data-tab="stats"] [data-i18n], #simpleNav .nav-btn[data-tab="stats"] [data-i18n]',
    )
    .forEach((el) => apply(el, on ? "ghAnalytics" : "stats"));
  ["moreNavBtn", "moreNavBtnSimple"].forEach((id) => {
    apply(
      document.querySelector(`#${id} [data-i18n]`),
      on ? "ghProfile" : "moreLabel",
    );
  });
}

function applyColorTheme(themeKey) {
  colorTheme = themeKey || "dark";
  localStorage.setItem("colorTheme", colorTheme);
  const theme = COLOR_THEMES[colorTheme];
  if (!theme) return;
  [
    "theme-white",
    "theme-default",
    "theme-sunset",
    "theme-ocean",
    "theme-dark",
    "theme-navy",
    "theme-gold",
    "theme-sunrise",
    "theme-graphiteNeon",
    "dark",
  ].forEach((cls) => document.body.classList.remove(cls));
  if (theme.dark) document.body.classList.add("dark");
  document.body.classList.add("theme-" + colorTheme);
  // Force re-render of hero gradient and nav for day themes
  if (!theme.dark) {
    const hc = document.querySelector(".balance-card");
    if (hc) {
      hc.style.transition = "background 0.4s ease";
    }
  }
  Object.entries(theme.vars || {}).forEach(([k, v]) =>
    document.body.style.setProperty(k, v),
  );
  document.getElementById("themeStars")?.remove();
  document.getElementById("themeShimmer")?.remove();
  document.getElementById("themeAurora")?.remove();
  const inj = (id, css) => {
    if (!document.getElementById(id)) {
      const s = document.createElement("style");
      s.id = id;
      s.textContent = css;
      document.head.appendChild(s);
    }
  };
  if (colorTheme === "navy") {
    const el = document.createElement("canvas");
    el.id = "themeStars";
    el.style.cssText =
      "position:fixed;inset:0;pointer-events:none;z-index:0;opacity:.7;";
    document.body.insertBefore(el, document.body.firstChild);
    const ctx = el.getContext("2d");
    function ds() {
      el.width = window.innerWidth;
      el.height = window.innerHeight;
      ctx.clearRect(0, 0, el.width, el.height);
      const n = Math.floor((el.width * el.height) / 6000);
      for (let i = 0; i < n; i++) {
        const x = Math.random() * el.width,
          y = Math.random() * el.height,
          r = Math.random() * 1.5 + 0.3;
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${180 + ~~(Math.random() * 75)},${200 + ~~(Math.random() * 55)},255,${Math.random() * 0.8 + 0.2})`;
        ctx.fill();
      }
    }
    ds();
    window.addEventListener("resize", ds, { once: true });
  }
  if (colorTheme === "gold") {
    inj(
      "goldKf",
      "@keyframes goldFloat{0%{transform:translateY(0) rotate(0deg);opacity:0}20%{opacity:1}100%{transform:translateY(-120px) rotate(360deg);opacity:0}}",
    );
    const el = document.createElement("div");
    el.id = "themeShimmer";
    el.style.cssText =
      "position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden;";
    for (let i = 0; i < 18; i++) {
      const p = document.createElement("div");
      const sz = Math.random() * 4 + 2;
      p.style.cssText = `position:absolute;width:${sz}px;height:${sz}px;border-radius:50%;background:rgba(200,149,42,.7);left:${Math.random() * 100}%;bottom:${Math.random() * 30 - 10}%;animation:goldFloat ${4 + Math.random() * 8}s ${Math.random() * 6}s ease-in infinite;`;
      el.appendChild(p);
    }
    document.body.insertBefore(el, document.body.firstChild);
  }
  if (colorTheme === "sunset") {
    // Живой эффект восхода/заката
    inj(
      "sunsetKf",
      `
      @keyframes sunRise {
        0%   { transform: translateY(60px) scale(0.7); opacity: 0.2; }
        40%  { opacity: 1; }
        100% { transform: translateY(-30px) scale(1.1); opacity: 0.85; }
      }
      @keyframes sunPulse {
        0%,100% { box-shadow: 0 0 40px 10px rgba(251,146,60,0.35), 0 0 80px 30px rgba(251,146,60,0.15); }
        50%     { box-shadow: 0 0 70px 20px rgba(251,146,60,0.55), 0 0 140px 60px rgba(251,146,60,0.25); }
      }
      @keyframes cloudDrift {
        0%   { transform: translateX(-60px); opacity: 0; }
        15%  { opacity: 0.7; }
        85%  { opacity: 0.7; }
        100% { transform: translateX(110vw); opacity: 0; }
      }
      @keyframes skyGlow {
        0%,100% { opacity: 0.55; }
        50%     { opacity: 0.9; }
      }
      @keyframes rayRotate {
        0%   { transform: rotate(0deg); opacity: 0.18; }
        50%  { opacity: 0.32; }
        100% { transform: rotate(360deg); opacity: 0.18; }
      }
    `,
    );
    const wrap = document.createElement("div");
    wrap.id = "themeAurora";
    wrap.style.cssText =
      "position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden;";

    // Небесный градиент
    const sky = document.createElement("div");
    sky.style.cssText =
      "position:absolute;inset:0;background:linear-gradient(180deg,rgba(251,146,60,0.13) 0%,rgba(251,191,36,0.09) 40%,transparent 100%);animation:skyGlow 6s ease-in-out infinite;";
    wrap.appendChild(sky);

    // Солнце
    const sun = document.createElement("div");
    sun.style.cssText =
      "position:absolute;left:50%;bottom:18%;width:64px;height:64px;margin-left:-32px;border-radius:50%;background:radial-gradient(circle,#fde68a 0%,#fb923c 60%,rgba(251,146,60,0) 100%);animation:sunRise 8s ease-out forwards, sunPulse 4s 2s ease-in-out infinite;";
    wrap.appendChild(sun);

    // Лучи солнца
    const rays = document.createElement("div");
    rays.style.cssText =
      "position:absolute;left:50%;bottom:calc(18% + 32px);width:160px;height:160px;margin-left:-80px;margin-bottom:-80px;background:conic-gradient(rgba(251,191,36,0.18) 0deg,transparent 30deg,rgba(251,191,36,0.14) 60deg,transparent 90deg,rgba(251,191,36,0.18) 120deg,transparent 150deg,rgba(251,191,36,0.14) 180deg,transparent 210deg,rgba(251,191,36,0.18) 240deg,transparent 270deg,rgba(251,191,36,0.14) 300deg,transparent 330deg,rgba(251,191,36,0.18) 360deg);border-radius:50%;animation:rayRotate 12s linear infinite;";
    wrap.appendChild(rays);

    // Облака
    const cloudColors = [
      "rgba(251,191,36,0.22)",
      "rgba(251,146,60,0.18)",
      "rgba(253,186,116,0.20)",
    ];
    [
      { w: 180, h: 38, b: "28%", delay: "0s", dur: "18s", top: "auto" },
      { w: 120, h: 26, b: "38%", delay: "5s", dur: "24s", top: "auto" },
      { w: 220, h: 32, b: "22%", delay: "10s", dur: "30s", top: "auto" },
    ].forEach((c, i) => {
      const cloud = document.createElement("div");
      cloud.style.cssText = `position:absolute;left:-220px;bottom:${c.b};width:${c.w}px;height:${c.h}px;border-radius:999px;background:${cloudColors[i]};filter:blur(8px);animation:cloudDrift ${c.dur} ${c.delay} linear infinite;`;
      wrap.appendChild(cloud);
    });

    // Горизонтальное сияние
    const glow = document.createElement("div");
    glow.style.cssText =
      "position:absolute;left:0;right:0;bottom:16%;height:60px;background:linear-gradient(transparent,rgba(251,191,36,0.22),transparent);filter:blur(8px);animation:skyGlow 5s 1s ease-in-out infinite;";
    wrap.appendChild(glow);

    document.body.insertBefore(wrap, document.body.firstChild);
  }

  if (colorTheme === "white") {
    // Золотой час — мягкое утреннее солнце с частицами пыльцы
    inj(
      "whiteKf",
      `
      @keyframes goldenRise {
        0%   { transform: translateY(40px); opacity: 0; }
        100% { transform: translateY(0px); opacity: 1; }
      }
      @keyframes goldenPulse {
        0%,100% { box-shadow: 0 0 50px 15px rgba(251,191,36,0.3), 0 0 100px 40px rgba(251,191,36,0.12); }
        50%     { box-shadow: 0 0 80px 25px rgba(251,191,36,0.5), 0 0 160px 70px rgba(251,191,36,0.2); }
      }
      @keyframes goldenFloat {
        0%   { transform: translateY(0) translateX(0) rotate(0deg); opacity: 0; }
        15%  { opacity: 0.8; }
        85%  { opacity: 0.6; }
        100% { transform: translateY(-140px) translateX(${Math.random() > 0.5 ? "" : "-"}30px) rotate(180deg); opacity: 0; }
      }
      @keyframes goldenGlow {
        0%,100% { opacity: 0.4; }
        50%     { opacity: 0.75; }
      }
      @keyframes goldenRay {
        0%   { transform: rotate(0deg); opacity: 0.12; }
        100% { transform: rotate(360deg); opacity: 0.12; }
      }
    `,
    );
    const wrap = document.createElement("div");
    wrap.id = "themeShimmer";
    wrap.style.cssText =
      "position:fixed;inset:0;pointer-events:none;z-index:0;overflow:hidden;";

    // Фоновое сияние
    const bg = document.createElement("div");
    bg.style.cssText =
      "position:absolute;inset:0;background:radial-gradient(ellipse 90% 60% at 30% 80%,rgba(251,191,36,0.18) 0%,rgba(251,146,60,0.10) 40%,transparent 75%);animation:goldenGlow 7s ease-in-out infinite;";
    wrap.appendChild(bg);

    // Солнце низко у горизонта
    const sun = document.createElement("div");
    sun.style.cssText =
      "position:absolute;left:28%;bottom:12%;width:80px;height:80px;border-radius:50%;background:radial-gradient(circle,#fef3c7 0%,#fde68a 40%,#fb923c 75%,rgba(251,146,60,0) 100%);animation:goldenRise 2s ease-out forwards, goldenPulse 5s 2s ease-in-out infinite;";
    wrap.appendChild(sun);

    // Лучи
    const rays = document.createElement("div");
    rays.style.cssText =
      "position:absolute;left:28%;bottom:calc(12% + 40px);width:200px;height:200px;margin-left:-60px;margin-bottom:-100px;background:conic-gradient(rgba(251,191,36,0.15) 0deg,transparent 25deg,rgba(251,191,36,0.12) 50deg,transparent 75deg,rgba(251,191,36,0.15) 100deg,transparent 125deg,rgba(251,191,36,0.12) 150deg,transparent 175deg,rgba(251,191,36,0.15) 200deg,transparent 225deg,rgba(251,191,36,0.12) 250deg,transparent 275deg,rgba(251,191,36,0.15) 300deg,transparent 325deg,rgba(251,191,36,0.12) 350deg,transparent 360deg);border-radius:50%;animation:goldenRay 20s linear infinite;";
    wrap.appendChild(rays);

    // Частицы пыльцы/пыли
    for (let i = 0; i < 22; i++) {
      const p = document.createElement("div");
      const sz = Math.random() * 5 + 2;
      const colors = [
        "rgba(251,191,36,0.7)",
        "rgba(251,146,60,0.6)",
        "rgba(253,224,71,0.65)",
        "rgba(252,211,77,0.7)",
      ];
      p.style.cssText = `position:absolute;width:${sz}px;height:${sz}px;border-radius:50%;background:${colors[~~(Math.random() * colors.length)]};left:${Math.random() * 100}%;bottom:${Math.random() * 40}%;filter:blur(${Math.random() < 0.4 ? 1 : 0}px);animation:goldenFloat ${5 + Math.random() * 10}s ${Math.random() * 8}s ease-in-out infinite;`;
      wrap.appendChild(p);
    }

    // Горизонтальная дымка
    const haze = document.createElement("div");
    haze.style.cssText =
      "position:absolute;left:0;right:0;bottom:10%;height:80px;background:linear-gradient(transparent,rgba(251,191,36,0.18),transparent);filter:blur(12px);animation:goldenGlow 6s ease-in-out infinite;";
    wrap.appendChild(haze);

    document.body.insertBefore(wrap, document.body.firstChild);
  }
  // Force CSS recalc for all themed elements
  requestAnimationFrame(() => {
    document
      .querySelectorAll(
        ".balance-card, .nav-fab-circle, .app-logo, .btn-primary",
      )
      .forEach((el) => {
        el.style.transition = "all 0.35s ease";
      });
    // Trigger repaint
    void document.body.offsetHeight;
  });
  syncGraphiteShell();
}

function getCategoryStyle(cat, type) {
  const baseStyle = getBaseCategoryStyle(cat, type);
  const custom = categoryCustomizations?.[cat] || {};
  return {
    // Эмодзи — через общий резолвер: свой, затем сохранённый в категории,
    // затем подобранный по названию. Список категорий и история берут иконку
    // отсюда, поэтому подмена или потеря одного источника больше не «съедает»
    // выбранный пользователем эмодзи.
    icon: getCategoryEmoji(cat, type, baseStyle.icon),
    color: normalizeHexColor(custom.color) || baseStyle.color,
  };
}

// ============================================================
// ШАБЛОНЫ
// ============================================================
let userTemplates = [];
let frequentStats = {};

function saveFrequentStats() {
  localStorage.setItem("frequentStats", JSON.stringify(frequentStats));
}
function saveUserTemplates() {
  localStorage.setItem("userTemplates", JSON.stringify(userTemplates));
}
function loadUserTemplates() {
  const r = localStorage.getItem("userTemplates");
  if (r) userTemplates = JSON.parse(r);
}
function updateFrequentStats(tx) {
  const k = `${tx.category}|${tx.amountRub}`;
  frequentStats[k] = (frequentStats[k] || 0) + 1;
  saveFrequentStats();
}
function getFrequentSuggestions(limit = 5) {
  return Object.entries(frequentStats)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([k, c]) => {
      const [cat, amt] = k.split("|");
      return {
        type: "auto",
        category: cat,
        amountRub: parseFloat(amt),
        count: c,
      };
    });
}
// Удаление быстрого предложения из списка «⚡ Быстрые предложения».
// Убирается только сама запись статистики частоты: массив transactions
// и баланс при этом не меняются — история операций остаётся нетронутой.
function removeFrequentSuggestion(category, amountRub) {
  const target = Number(amountRub);
  if (!Number.isFinite(target)) return false;
  let removed = false;
  Object.keys(frequentStats).forEach((key) => {
    const sep = key.lastIndexOf("|");
    if (sep < 0) return;
    const cat = key.slice(0, sep);
    const amt = parseFloat(key.slice(sep + 1));
    if (cat !== category || !Number.isFinite(amt)) return;
    if (Math.abs(amt - target) > 0.005) return;
    delete frequentStats[key];
    removed = true;
  });
  if (removed) saveFrequentStats();
  return removed;
}

// Включение/выключение блока «Быстрые предложения».
// Новый ключ — источник истины, прежний ключ дублируется для старого экрана.
function setQuickSuggestionsEnabled(enabled) {
  suggestionsEnabled = !!enabled;
  const value = suggestionsEnabled ? "true" : "false";
  try {
    localStorage.setItem(QUICK_SUGGESTIONS_STORAGE_KEY, value);
    localStorage.setItem(LEGACY_SUGGESTIONS_STORAGE_KEY, value);
  } catch (e) {}
  updateSuggestions();
  return suggestionsEnabled;
}

function addUserTemplate(tpl) {
  userTemplates.push({ id: Date.now(), ...tpl });
  saveUserTemplates();
}
function removeUserTemplate(id) {
  userTemplates = userTemplates.filter((t) => t.id !== id);
  saveUserTemplates();
}

// Рендер блока «Быстрые предложения» с кнопкой удаления у каждой карточки.
function updateSuggestions() {
  const block = document.getElementById("suggestionsBlock");
  const sl = document.getElementById("suggestionsList");
  if (!sl) return;
  // Выключенный переключатель полностью убирает блок из окна добавления.
  if (!suggestionsEnabled) {
    sl.innerHTML = "";
    if (block) block.style.display = "none";
    return;
  }
  if (block) block.style.display = "";

  const auto = getFrequentSuggestions(3);
  const manual = userTemplates.slice(0, 5);
  const deleteLabel = t("quickSuggestionDeleteTitle");
  let html = "";
  if (auto.length) {
    html += `<div class="suggestions-subtitle">⚡ ${t("quickSuggestions")}</div>`;
    auto.forEach((s) => {
      html += `<div class="suggestion-item-wrap">
        <button class="suggestion-item" data-type="auto" data-category="${esc(s.category)}" data-amount="${s.amountRub}"><span>📌 ${esc(s.category)} · ${fmt(s.amountRub)}</span></button>
        <button class="suggestion-delete-btn" type="button" data-kind="auto" data-category="${esc(s.category)}" data-amount="${s.amountRub}" title="${esc(deleteLabel)}" aria-label="${esc(deleteLabel)}">✕</button>
      </div>`;
    });
  }
  if (manual.length) {
    html += `<div class="suggestions-subtitle">⭐ ${t("yourTemplates")}</div>`;
    manual.forEach((tpl) => {
      const icon = tpl.type === "expense" ? "💸" : "💰";
      html += `<div class="suggestion-item-wrap">
        <button class="suggestion-item" data-type="manual" data-id="${tpl.id}" data-category="${esc(tpl.category)}" data-subcategory="${esc(tpl.subcategory || "")}" data-amount="${tpl.amountRub}" data-note="${esc(tpl.note || "")}">
          <span>${icon} ${esc(tpl.name)} · ${fmt(tpl.amountRub)}</span>
        </button>
        <button class="suggestion-delete-btn" type="button" data-kind="manual" data-id="${tpl.id}" title="${esc(deleteLabel)}" aria-label="${esc(deleteLabel)}">✕</button>
      </div>`;
    });
  }
  if (!auto.length && !manual.length)
    html = `<div class="suggestions-empty">${t("noStatsYet")}</div>`;
  sl.innerHTML = html;

  // Обработчики применения
  sl.querySelectorAll(".suggestion-item").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (btn.dataset.type === "auto") {
        const cs = document.getElementById("addCategorySelect");
        if (cs) {
          cs.value = btn.dataset.category;
          cs.dispatchEvent(new Event("change"));
        }
        const af = document.getElementById("addAmount");
        if (af) af.value = toDisp(parseFloat(btn.dataset.amount)).toFixed(2);
      } else {
        const tpl = userTemplates.find(
          (t) => t.id === parseInt(btn.dataset.id),
        );
        if (!tpl) return;
        addType = tpl.type;
        const modal = document.getElementById("addModal");
        if (modal) {
          modal
            .querySelectorAll(".type-btn")
            .forEach((b) => b.classList.remove("active"));
          const tb = modal.querySelector(`.type-btn.${tpl.type}`);
          if (tb) tb.classList.add("active");
        }
        document.getElementById("catLabel").textContent =
          tpl.type === "expense" ? t("expCategory") : t("incCategory");
        const cs = document.getElementById("addCategorySelect");
        const eo =
          `<option value="">${t("selectCategory")}</option>` +
          Object.keys(categories)
            .map((c) => `<option value="${c}">${c}</option>`)
            .join("");
        const io =
          `<option value="">${t("selectCategory")}</option>` +
          Object.keys(incomeCategories)
            .map((c) => `<option value="${c}">${c}</option>`)
            .join("");
        cs.innerHTML = tpl.type === "expense" ? eo : io;
        cs.value = tpl.category;
        cs.dispatchEvent(new Event("change"));
        if (tpl.subcategory) {
          setTimeout(() => {
            const s = document.getElementById("addSubcatSelect");
            if (s) { s.value = tpl.subcategory; s.dispatchEvent(new Event("change")); }
          }, 50);
        }
        const af = document.getElementById("addAmount");
        if (af) af.value = toDisp(tpl.amountRub).toFixed(2);
        if (tpl.note) document.getElementById("addNote").value = tpl.note;
      }
    });
  });

  // Обработчики удаления: убирается только само предложение, история операций
  // и баланс не меняются.
  sl.querySelectorAll(".suggestion-delete-btn").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const kind = btn.dataset.kind === "auto" ? "auto" : "manual";
      askConfirm(
        t("quickSuggestionDeleteMsg"),
        () => {
          if (kind === "auto") {
            if (!removeFrequentSuggestion(btn.dataset.category, btn.dataset.amount)) return;
          } else {
            removeUserTemplate(parseInt(btn.dataset.id, 10));
          }
          updateSuggestions();
          showToast(t("quickSuggestionDeleted"));
        },
        { icon: "🗑️", title: t("quickSuggestionDeleteTitle") },
      );
    });
  });
}

let calcExpr = "";

// ============================================================
// УТИЛИТЫ
// ============================================================
function toDisp(rub) {
  return rub * (exchangeRates[displayCurrency] || 1);
}
function toRub(disp) {
  return disp / (exchangeRates[displayCurrency] || 1);
}
function localCalendarDate(date = new Date()) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`;
}
function today() {
  return localCalendarDate();
}
function fmtDate(d) {
  if (!d) return "";
  try {
    return new Date(d + "T00:00:00").toLocaleDateString(currentLang);
  } catch (e) {
    return d;
  }
}
function esc(str) {
  if (!str) return "";
  return String(str).replace(
    /[&<>"']/g,
    (m) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        m
      ],
  );
}
function fmt(n) {
  return toDisp(n).toFixed(2) + " " + sym();
}
function cleanMoneyValue(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  return Math.round(n * 100) / 100;
}
function parseMoneyInput(value) {
  return Number(
    String(value || "")
      .replace(",", ".")
      .replace(/\s+/g, ""),
  );
}
function isInitialBalanceTx(tx) {
  return (
    !!tx &&
    (tx._initial === true ||
      tx.type === "salary" ||
      tx.id === "__initial_balance__" ||
      tx.category === "Начальная сумма" ||
      tx.category === "Starting amount" ||
      tx.category === "საწყისი თანხა")
  );
}
function normalizeFinancialState() {
  const diagnosticsBeforeState = buildTransactionDiagnosticsState(transactions, {
    includeSample: true,
  });
  logTransactionsDiag("[TX_SOURCE]", "normalizeFinancialState:start");
  logTransactionsDiag("[TX_BEFORE]", "normalizeFinancialState:before-normalize");
  const normalizedStartBalanceRub = Math.max(0, cleanMoneyValue(startBalanceRub));
  if (normalizedStartBalanceRub !== startBalanceRub) {
    logStartBalanceWrite(
      "normalizeFinancialState",
      startBalanceRub,
      normalizedStartBalanceRub,
    );
  }
  startBalanceRub = normalizedStartBalanceRub;
  const seenIds = new Set();
  const clean = [];
  for (const tx of transactions || []) {
    if (!tx || isInitialBalanceTx(tx)) continue;
    const amountRub = cleanMoneyValue(tx.amountRub);
    if (amountRub <= 0) continue;
    const next = {
      ...tx,
      id:
        tx.id ||
        `${tx.date || today()}_${tx.type || "expense"}_${amountRub}_${clean.length}`,
      type: tx.type === "income" ? "income" : "expense",
      amountRub,
      date: tx.date || today(),
    };
    if (seenIds.has(next.id)) continue;
    seenIds.add(next.id);
    clean.push(next);
  }
  if (startBalanceRub > 0) {
    clean.unshift({
      id: "__initial_balance__",
      type: "income",
      category: t("initialCategory"),
      subcategory: null,
      amountRub: startBalanceRub,
      date: today(),
      note: t("initialCapital"),
      _initial: true,
      lockedInitial: true,
    });
  }
  logTransactionsDiag("[TX_BEFORE]", "normalizeFinancialState:before-transactions-assign", {
    nextTransactionsLength: clean.length,
    nextTransactions: clean.slice(0, 20).map((tx) => ({
      id: tx?.id ?? null,
      amountRub: tx?.amountRub ?? null,
      type: tx?.type ?? null,
      date: tx?.date ?? null,
    })),
  });
  const diagnosticsAfterState = buildTransactionDiagnosticsState(clean, {
    includeSample: true,
  });
  transactions = clean;
  logTransactionsDiag("[TX_AFTER]", "normalizeFinancialState:after-transactions-assign");
  logTransactionsDiagnosticTransition(
    "TX_NORMALIZE",
    "normalizeFinancialState",
    diagnosticsBeforeState,
    diagnosticsAfterState,
    {
      kind: "normalize",
    },
  );
}
function getMoneyTransactions() {
  return (transactions || []).filter((tx) => !isInitialBalanceTx(tx));
}
function debounce(fn, delay) {
  let t;
  return function (...a) {
    clearTimeout(t);
    t = setTimeout(() => fn.apply(this, a), delay);
  };
}

// Хеш пин-кода (простой, без сервера)

function getDateGroupLabel(dateStr) {
  const todayStr = today();
  const d = new Date();
  d.setDate(d.getDate() - 1);
  const yesterdayStr = localCalendarDate(d);
  if (dateStr === todayStr) return t("groupToday");
  if (dateStr === yesterdayStr) return t("groupYesterday");
  try {
    return new Date(dateStr + "T00:00:00").toLocaleDateString(currentLang, {
      day: "numeric",
      month: "long",
    });
  } catch (e) {
    return dateStr;
  }
}

// Фильтрация по времени для истории
function filterByTime(txList, filter) {
  const now = new Date();
  const todayStr = today();
  const d1 = new Date();
  d1.setDate(d1.getDate() - 1);
  const yesterdayStr = localCalendarDate(d1);
  const d2 = new Date();
  d2.setDate(d2.getDate() - 2);
  const twoDaysStr = localCalendarDate(d2);
  const weekStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  weekStart.setDate(weekStart.getDate() - ((weekStart.getDay() + 6) % 7));
  const weekEnd = new Date(weekStart);
  weekEnd.setDate(weekEnd.getDate() + 6);
  const monthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  const inRange = (from, to) => txList.filter(
    (tx) => tx.date && tx.date >= localCalendarDate(from) && tx.date <= localCalendarDate(to),
  );
  switch (filter) {
    case "today":
      return txList.filter((tx) => tx.date === todayStr);
    case "yesterday":
      return txList.filter((tx) => tx.date === yesterdayStr);
    case "twoDaysAgo":
      return txList.filter((tx) => tx.date === twoDaysStr);
    case "thisWeek":
      return inRange(weekStart, weekEnd);
    case "thisMonth":
      return inRange(new Date(now.getFullYear(), now.getMonth(), 1), monthEnd);
    default:
      return txList;
  }
}

// All screens share the same money totals; initial balance is counted only once.
function getFinancialTotals(txList = getMoneyTransactions()) {
  let income = 0, expense = 0;
  for (const tx of txList) {
    if (isInitialBalanceTx(tx)) continue;
    if (tx.type === "income") income += tx.amountRub;
    else if (tx.type === "expense") expense += tx.amountRub;
  }
  return { income, expense, balance: startBalanceRub + income - expense };
}

// Кнопки периода «Период:» в блоке деталей должны совпадать с historyFilter.
function syncHistoryFilterChips() {
  const buttons = document.querySelectorAll ? document.querySelectorAll(".htf-btn") : [];
  buttons.forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.hf === (historyFilter || "allTime"));
  });
}

// Карточка «Доходы»/«Расходы»: повторное нажатие снимает фильтр и возвращает
// историю в исходное состояние (раньше фильтр только выставлялся заново).
// Фильтр по типу НЕ ограничивает период: суммы на карточках считаются за всё
// время, поэтому в истории должны остаться все операции этого типа, включая
// прошлые месяцы (иначе июньский доход «исчезал» из списка). Параметр
// cardPeriod оставлен для совместимости вызовов и на период не влияет.
function toggleHistoryFilter(type, cardPeriod) {
  if (currentFilter === type) {
    currentFilter = null;
    historyFilter = "allTime";
  } else {
    currentFilter = type;
    historyFilter = "allTime";
  }
  syncHistoryFilterChips();
  return currentFilter;
}

// Карточка «Баланс» и кнопка сброса: убираем и фильтр по типу, и по периоду.
function resetHistoryFilter() {
  currentFilter = null;
  historyFilter = "allTime";
  syncHistoryFilterChips();
  return currentFilter;
}

// Прокрутка к началу истории после смены фильтра по типу.
// Раньше здесь вызывался scrollIntoView на самом списке: цель считалась по
// геометрии до перерисовки, а липкая шапка (.app-header, position: sticky)
// перекрывала верх блока — список останавливался ниже своего верха, а при
// снятии фильтра (список снова длинный) уезжал в середину. Теперь прокручивается
// страница (скроллер — window), явно к верху блока истории, с поправкой на
// высоту липкой шапки.
function scrollHistoryToTop() {
  const byId = (id) =>
    document.getElementById ? document.getElementById(id) : null;
  const listEl =
    byId("opsList") ||
    (document.querySelector
      ? document.querySelector(".sm-recent-block")
      : null) ||
    byId("homeOpsItems");
  if (!listEl || typeof listEl.getBoundingClientRect !== "function") return false;
  const header = document.querySelector
    ? document.querySelector(".app-header")
    : null;
  const headerHeight =
    header && typeof header.getBoundingClientRect === "function"
      ? Math.max(0, Math.round(header.getBoundingClientRect().height || 0))
      : 0;
  const rect = listEl.getBoundingClientRect();
  const pageY =
    typeof window !== "undefined" && window.scrollY ? window.scrollY : 0;
  const top = Math.max(0, Math.round(pageY + rect.top - headerHeight - 8));
  if (typeof window === "undefined" || typeof window.scrollTo !== "function")
    return false;
  window.scrollTo({ top, behavior: "smooth" });
  return true;
}

function getFilteredOperations(query = "") {
  const search = query.toLowerCase().trim();
  let filtered = getMoneyTransactions();
  if (currentFilter === "income" || currentFilter === "expense") {
    filtered = filtered.filter((tx) => tx.type === currentFilter);
  }
  filtered = filterByTime(filtered, historyFilter);
  if (search) {
    filtered = filtered.filter((tx) => {
      const amount = toDisp(tx.amountRub).toFixed(2);
      return [tx.category, tx.subcategory, tx.note, tx.date, amount,
        amount.replace(".", ",")].some((value) =>
          value != null && String(value).toLowerCase().includes(search));
    });
  }
  return filtered;
}

// Порядок операций «новые сверху». Дата хранится строкой YYYY-MM-DD, а поле
// time заполнено не у всех операций, поэтому при равенстве даты и времени
// сравниваем позицию в массиве transactions: она отражает порядок добавления
// (добавлено позже — выше в списке). Без этого новая операция за сегодня
// оставалась в конце своей дневной группы.
function sortOperationsNewestFirst(list) {
  const order = new Map();
  (transactions || []).forEach((tx, index) => order.set(tx, index));
  return (list || []).slice().sort((a, b) => {
    const byDate = `${b.date || ""} ${b.time || ""}`.localeCompare(
      `${a.date || ""} ${a.time || ""}`,
    );
    if (byDate !== 0) return byDate;
    return (order.get(b) ?? -1) - (order.get(a) ?? -1);
  });
}

function refreshOperationViews() {
  if (currentTab === "home" && simpleMode) {
    refreshHomeList();
    return;
  }
  updateTopBlocks();
  if (currentTab === "home") renderOpsList();
  else if (currentTab === "stats") renderStats();
  else if (currentTab === "categories") renderCategories();
}

function getTransactionsForPeriod(period) {
  const now = new Date();
  const y = now.getFullYear(),
    m = now.getMonth();
  if (period === "thisMonth")
    return transactions.filter((tx) => {
      if (!tx.date) return false;
      const d = new Date(tx.date + "T00:00:00");
      return d.getFullYear() === y && d.getMonth() === m;
    });
  if (period === "lastMonth") {
    const lm = m === 0 ? 11 : m - 1,
      ly = m === 0 ? y - 1 : y;
    return transactions.filter((tx) => {
      if (!tx.date) return false;
      const d = new Date(tx.date + "T00:00:00");
      return d.getFullYear() === ly && d.getMonth() === lm;
    });
  }
  return transactions;
}

