function bindAppearanceSettingsHandlers() {
  const cs2 = document.getElementById("currencySelect");
  if (cs2) cs2.value = displayCurrency;
  const ts = document.getElementById("themeSelect");
  if (ts)
    ts.value = document.body.classList.contains("dark") ? "dark" : "light";
  const ls = document.getElementById("langSelect");
  if (ls) ls.value = currentLang;
  const refreshAppearanceStates = () => {
    const currentThemeMode = document.body.classList.contains("dark")
      ? "dark"
      : "light";
    document.querySelectorAll("[data-theme-mode]").forEach((btn) => {
      btn.classList.toggle(
        "active",
        btn.dataset.themeMode === currentThemeMode,
      );
    });
    document.querySelectorAll("[data-language-choice]").forEach((btn) => {
      btn.classList.toggle(
        "active",
        btn.dataset.languageChoice === currentLang,
      );
    });
    document.querySelectorAll("[data-currency-choice]").forEach((btn) => {
      btn.classList.toggle(
        "active",
        btn.dataset.currencyChoice === displayCurrency,
      );
    });
    document.querySelectorAll("[data-time-format]").forEach((btn) => {
      btn.classList.toggle(
        "active",
        btn.dataset.timeFormat ===
          (localStorage.getItem("timeFormat12h") === "true" ? "12" : "24"),
      );
    });
    document.querySelectorAll(".font-size-btn, .set-font-btn").forEach((btn) => {
      btn.classList.toggle("active", btn.dataset.size === fontSize);
    });
  };

  document.querySelectorAll("[data-theme-mode]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (!ts) return;
      ts.value = btn.dataset.themeMode;
      ts.dispatchEvent(new Event("change"));
      refreshAppearanceStates();
    });
  });

  document.querySelectorAll("[data-language-choice]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (!ls) return;
      ls.value = btn.dataset.languageChoice;
      ls.dispatchEvent(new Event("change"));
    });
  });

  document.querySelectorAll("[data-currency-choice]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (!cs2) return;
      cs2.value = btn.dataset.currencyChoice;
      cs2.dispatchEvent(new Event("change"));
      refreshAppearanceStates();
    });
  });

  document.querySelectorAll("[data-time-format]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const toggle = document.getElementById("time12hToggle");
      if (!toggle) return;
      toggle.checked = btn.dataset.timeFormat === "12";
      toggle.dispatchEvent(new Event("change"));
      refreshAppearanceStates();
    });
  });

  cs2?.addEventListener("change", (e) => {
    displayCurrency = e.target.value;
    saveAll();
    refreshOperationViews();
    showToast(t("currencyChanged"));
  });

  ts?.addEventListener("change", (e) => {
    const isDark = e.target.value === "dark";
    if (isDark) {
      document.body.classList.add("dark");
      if (!COLOR_THEMES[colorTheme]?.dark) applyColorTheme("dark");
    } else {
      document.body.classList.remove("dark");
      if (COLOR_THEMES[colorTheme]?.dark) applyColorTheme("default");
    }
    localStorage.setItem("theme", e.target.value);
    showToast(t("themeChanged"));
    refreshAppearanceStates();
  });

  ls?.addEventListener("change", (e) => setLanguage(e.target.value));

  document.querySelectorAll(".set-theme-sw").forEach((btn) => {
    btn.addEventListener("click", () => {
      // Mark as manual override so time-theme doesn't auto-revert the choice
      localStorage.setItem("themeManualOverride", "1");
      applyColorTheme(btn.dataset.theme);
      showToast(
        "🎨 " + (tObj("themeLabels")[btn.dataset.theme] || btn.dataset.theme),
      );
      setTimeout(() => renderSettings(), 300);
    });
  });

  document.getElementById("resetThemeBtn")?.addEventListener("click", () => {
    applyColorTheme(
      document.body.classList.contains("dark") ? "dark" : "default",
    );
    showToast("🔄 " + t("resetThemeBtn"));
    setTimeout(() => renderSettings(), 300);
  });

  document
    .getElementById("simpleModeToggle")
    ?.addEventListener("change", (e) => {
      applySimpleMode(e.target.checked);
      showToast(e.target.checked ? t("simpleModeOn") : t("simpleModeOff"));
      renderSettings();
    });

  document
    .getElementById("showVoiceBtnToggle")
    ?.addEventListener("change", (e) => {
      const enabled = !!e.target.checked;
      syncVoiceButtonEnabled(enabled);
      if (enabled) {
        if (!document.getElementById("voiceInputBtn")) addVoiceButton();
        return;
      }
      detachVoiceButton();
    });

  // Блок «Месячный бюджет» на главной: карточка прячется/показывается без
  // перерисовки главной — карусель и её обработчики остаются на месте.
  document
    .getElementById("homeBudgetToggle")
    ?.addEventListener("change", (e) => {
      const enabled = !!e.target.checked;
      setHomeBudgetVisible(enabled);
      syncHomeBudgetCardVisibility();
      haptic("light");
      showToast(enabled ? t("homeBudgetShown") : t("homeBudgetHidden"));
    });

  // Блок «Быстрые предложения» в окне добавления операции.
  document
    .getElementById("quickSuggestionsToggle")
    ?.addEventListener("change", (e) => {
      const enabled = !!e.target.checked;
      setQuickSuggestionsEnabled(enabled);
      haptic("light");
      showToast(
        enabled ? t("quickSuggestionsEnabledOn") : t("quickSuggestionsEnabledOff"),
      );
    });

  document
    .getElementById("time12hToggle")
    ?.addEventListener("change", function () {
      localStorage.setItem("timeFormat12h", this.checked ? "true" : "false");
      haptic("light");
      showToast(
        {
          ru: "Формат времени изменён",
          en: "Time format changed",
          ka: "დრ. ფ. შეიცვალა",
        }[currentLang],
        "success",
      );
    });

  document.querySelectorAll(".font-size-btn, .set-font-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      applyFontSize(btn.dataset.size);
      haptic("light");
      renderSettings();
    });
  });

  refreshAppearanceStates();
}

let voiceSettingsUnsubscribe = null;

function cleanupVoiceSettingsScreen() {
  if (typeof voiceSettingsUnsubscribe === "function") {
    voiceSettingsUnsubscribe();
    voiceSettingsUnsubscribe = null;
  }
  window.BudgetPROVoiceModule?.disposeScreen?.();
}

function renderSettingsVoiceScreen() {
  ensureSettingsHomeStyles();
  cleanupVoiceSettingsScreen();
  voiceSettingsUnsubscribe = window.VoiceUI.renderSettings({
    container: document.getElementById("mainContent"), lang: currentLang,
    begin: startVoiceSession, use: parseVoiceInput, back: openSettingsHome,
    login: () => showAuthScreen("voice-settings"),
    floating: getFloatingBtnSetting("showVoiceBtn"),
    setFloating(enabled) { syncVoiceButtonEnabled(enabled); addVoiceButton(); },
    cloudConsent: getVoiceCloudConsent(),
    cloudLabel: t("voiceSettingsCloudLabel"),
    cloudHint: t("voiceSettingsCloudHint"),
    setCloudConsent(value) {
      setVoiceCloudConsent(value);
      showToast(value === "cloud" ? t("voiceSettingsCloudOn") : t("voiceSettingsCloudOff"));
    }
  });
}

