function ensureHeroWrapAnchor() {
  const heroWrap = document.getElementById("heroCardWrap");
  heroWrapAnchor = document.getElementById("heroCardAnchor") || heroWrapAnchor;
  if (!heroWrapAnchor || !heroWrapAnchor.isConnected) {
    const header = document.querySelector(".app-header");
    const mainScroll = document.querySelector(".main-scroll");
    heroWrapAnchor = document.createElement("div");
    heroWrapAnchor.id = "heroCardAnchor";
    if (header && header.parentNode) {
      header.parentNode.insertBefore(
        heroWrapAnchor,
        mainScroll || header.nextSibling,
      );
    }
  }
  if (heroWrap) {
    if (heroWrapAnchor && heroWrap.parentNode === heroWrapAnchor.parentNode) {
      heroWrapAnchor.parentNode?.insertBefore(heroWrapAnchor, heroWrap);
    }
    return heroWrap;
  }
  const recreated = createHeroWrapNode();
  if (heroWrapAnchor?.parentNode) {
    heroWrapAnchor.parentNode.insertBefore(
      recreated,
      heroWrapAnchor.nextSibling,
    );
  }
  return recreated;
}

function mountHeroIntoHome() {
  const heroWrap = ensureHeroWrapAnchor();
  const mainContent = document.getElementById("mainContent");
  if (!heroWrap || !mainContent) return;
  if (heroWrap.parentNode !== mainContent) {
    mainContent.insertBefore(heroWrap, mainContent.firstChild || null);
  }
}

function unmountHeroFromHome() {
  const heroWrap = ensureHeroWrapAnchor();
  if (!heroWrap || !heroWrapAnchor) return;
  if (heroWrap.parentNode !== heroWrapAnchor.parentNode) {
    heroWrapAnchor.parentNode?.insertBefore(
      heroWrap,
      heroWrapAnchor.nextSibling,
    );
  }
}

let suspendHomeHeroLifecycle = false;

function setSuspendHomeHeroLifecycle(value) {
  suspendHomeHeroLifecycle = !!value;
}

function wrapHomeHeroLifecycleFunction(fnName) {
  const fn = globalThis[fnName];
  if (typeof fn !== "function" || fn.__homeHeroLifecycleWrapped) return;
  const wrapped = function (...args) {
    if (suspendHomeHeroLifecycle) return;
    return fn.apply(this, args);
  };
  wrapped.__homeHeroLifecycleWrapped = true;
  wrapped.__homeHeroLifecycleOriginal = fn;
  globalThis[fnName] = wrapped;
}

[
  "restoreHomeHeroIfNeeded",
  "ensureHomeHeroStable",
  "updateHeroTrendText",
  "updateHeroChipLabels",
  "forceHeroChipLayout",
  "mountHeroIntoHome",
  "unmountHeroFromHome",
].forEach(wrapHomeHeroLifecycleFunction);

function ensureHeroWrapGuard() {
  const heroWrap = document.getElementById("heroCardWrap");
  if (!heroWrap) return;
  heroWrapObserver?.disconnect();
  heroWrapObserver = new MutationObserver(() => {
    if (currentTab !== "home" || simpleMode) return;
    const hiddenByStyle =
      heroWrap.style.display === "none" ||
      heroWrap.style.visibility === "hidden" ||
      heroWrap.style.opacity === "0";
    if (hiddenByStyle) {
      restoreHomeHeroIfNeeded();
    }
  });
  heroWrapObserver.observe(heroWrap, {
    attributes: true,
    attributeFilter: ["style", "class"],
  });
}

function updateHeroDebugOverlay() {
  if (localStorage.getItem("heroDebug") !== "1") {
    document.getElementById("heroDebugOverlay")?.remove();
    return;
  }
  let dbg = document.getElementById("heroDebugOverlay");
  if (!dbg) {
    dbg = document.createElement("div");
    dbg.id = "heroDebugOverlay";
    dbg.style.cssText =
      "position:fixed;left:8px;top:8px;z-index:20000;background:rgba(0,0,0,.82);color:#fff;padding:8px 10px;border-radius:10px;font:12px/1.35 monospace;max-width:calc(100vw - 16px);white-space:pre-wrap;pointer-events:none;";
    document.body.appendChild(dbg);
  }
  const heroWrap = document.getElementById("heroCardWrap");
  const parentId =
    heroWrap?.parentElement?.id ||
    heroWrap?.parentElement?.className ||
    "(none)";
  const rect =
    heroWrap && heroWrap.getBoundingClientRect
      ? heroWrap.getBoundingClientRect()
      : null;
  dbg.textContent =
    "tab=" +
    currentTab +
    " | simple=" +
    simpleMode +
    "\nhero=" +
    !!heroWrap +
    " | parent=" +
    parentId +
    "\ndisplay=" +
    (heroWrap?.style.display || "(empty)") +
    " | vis=" +
    (heroWrap?.style.visibility || "(empty)") +
    " | op=" +
    (heroWrap?.style.opacity || "(empty)") +
    "\nrect=" +
    (rect ? Math.round(rect.width) + "x" + Math.round(rect.height) : "none");
}

function traceApp(event, details = {}) {
  if (!APP_TRACE_ENABLED) return;
  const timestamp = new Date().toLocaleTimeString("en-GB", {
    hour12: false,
  });
  let detailText = "";
  try {
    detailText = Object.keys(details).length
      ? " " + JSON.stringify(details)
      : "";
  } catch (e) {
    detailText = " [unserializable]";
  }
  const line = `${timestamp} ${event}${detailText}`;
  console.log("[BPTRACE]", line);
  try {
    if (
      window.BudgetPROTrace &&
      typeof window.BudgetPROTrace.log === "function"
    ) {
      window.BudgetPROTrace.log(line);
    }
  } catch (e) {}
  appTraceLines.push(line);
  if (appTraceLines.length > 12) appTraceLines.shift();

  if (!appTracePanel) {
    appTracePanel = document.createElement("div");
    appTracePanel.id = "appTracePanel";
    appTracePanel.style.cssText =
      "position:fixed;left:8px;right:8px;bottom:88px;z-index:20001;" +
      "background:rgba(0,0,0,.82);color:#fff;border-radius:12px;" +
      "padding:8px 10px;font:11px/1.35 monospace;max-height:180px;" +
      "overflow:auto;white-space:pre-wrap;pointer-events:none;" +
      "box-shadow:0 10px 30px rgba(0,0,0,.35);";
    document.body.appendChild(appTracePanel);
  }
  appTracePanel.textContent = appTraceLines.join("\n");
}

function attachAppTraceObservers() {
  if (!APP_TRACE_ENABLED) return;
  const mainContent = document.getElementById("mainContent");
  if (mainContent) {
    appTraceMainObserver?.disconnect();
    appTraceMainObserver = new MutationObserver(() => {
      const heroWrap = document.getElementById("heroCardWrap");
      traceApp("mainContent-mutated", {
        heroExists: !!heroWrap,
        heroParent:
          heroWrap?.parentElement?.id ||
          heroWrap?.parentElement?.className ||
          null,
        childCount: mainContent.children.length,
      });
      attachAppTraceObservers();
    });
    appTraceMainObserver.observe(mainContent, { childList: true });
  }

  const heroWrap = document.getElementById("heroCardWrap");
  if (heroWrap) {
    appTraceHeroObserver?.disconnect();
    appTraceHeroObserver = new MutationObserver(() => {
      const rect = heroWrap.getBoundingClientRect?.();
      traceApp("hero-mutated", {
        display: heroWrap.style.display || "",
        visibility: heroWrap.style.visibility || "",
        opacity: heroWrap.style.opacity || "",
        parent:
          heroWrap.parentElement?.id ||
          heroWrap.parentElement?.className ||
          null,
        rect: rect
          ? `${Math.round(rect.width)}x${Math.round(rect.height)}`
          : null,
      });
    });
    appTraceHeroObserver.observe(heroWrap, {
      attributes: true,
      attributeFilter: ["style", "class"],
    });
  }
}

function installHomeLayoutRuntimeAudit() {
  if (window.__homeLayoutRuntimeAuditInstalled) return;
  window.__homeLayoutRuntimeAuditInstalled = true;

  const stylePropsToTrace = new Set([
    "height",
    "min-height",
    "minHeight",
    "max-height",
    "maxHeight",
    "display",
    "transform",
    "scale",
    "flex",
    "flex-grow",
    "flexGrow",
    "flex-shrink",
    "flexShrink",
    "grid-template-rows",
    "gridTemplateRows",
    "padding",
    "padding-top",
    "paddingTop",
    "padding-right",
    "paddingRight",
    "padding-bottom",
    "paddingBottom",
    "padding-left",
    "paddingLeft",
    "margin",
    "margin-top",
    "marginTop",
    "margin-right",
    "marginRight",
    "margin-bottom",
    "marginBottom",
    "margin-left",
    "marginLeft",
  ]);
  const resizeState = new WeakMap();
  const observedParentNodes = new WeakSet();
  const writeState = new WeakMap();
  let resizeObserver = null;
  let bodyObserver = null;
  let visualViewportState = null;

  const nowTs = () => new Date().toISOString();
  const getStack = () => {
    const stack = new Error().stack || "";
    return stack
      .split("\n")
      .slice(2)
      .join("\n");
  };
  const describeEl = (el) => {
    if (!el) return "(null)";
    if (el === document.documentElement) return "html";
    if (el === document.body) return "body";
    const parts = [el.tagName?.toLowerCase() || "node"];
    if (el.id) parts.push(`#${el.id}`);
    if (el.classList?.length) {
      parts.push("." + Array.from(el.classList).join("."));
    }
    return parts.join("");
  };
  const getNearestScrollContainer = () => {
    const balanceCard = document.getElementById("balanceCard");
    let node = balanceCard?.parentElement || null;
    while (node && node !== document.body) {
      const cs = getComputedStyle(node);
      const overflowValue = `${cs.overflow} ${cs.overflowY} ${cs.overflowX}`;
      if (/(auto|scroll|overlay)/.test(overflowValue)) return node;
      node = node.parentElement;
    }
    return document.scrollingElement || document.documentElement;
  };
  const getTrackedNodes = () => {
    const tracked = [
      document.getElementById("balanceCard"),
      document.getElementById("heroCardWrap"),
      document.getElementById("mainContent"),
      document.getElementById("homeTab"),
      getNearestScrollContainer(),
      document.documentElement,
      document.body,
    ].filter(Boolean);
    return Array.from(new Set(tracked));
  };
  const isTrackedElement = (el) => getTrackedNodes().includes(el);
  const findOwnerByStyle = (styleDecl) => {
    const nodes = getTrackedNodes();
    for (const node of nodes) {
      if (node?.style === styleDecl) return node;
    }
    return null;
  };
  const recordWrite = (el, payload) => {
    if (!el) return;
    writeState.set(el, {
      timestamp: Date.now(),
      ...payload,
    });
  };
  const getRecentWrite = (el) => {
    const last = writeState.get(el);
    if (!last) return null;
    if (Date.now() - last.timestamp > 2000) return null;
    return last;
  };
  const logJson = (label, payload) => {
    console.log(`[${label}] ${JSON.stringify(payload)}`);
  };
  const observeParentChain = () => {
    const balanceCard = document.getElementById("balanceCard");
    let node = balanceCard?.parentElement || null;
    while (node) {
      if (!observedParentNodes.has(node)) {
        const parentObserver = new MutationObserver((mutations) => {
          mutations.forEach((mutation) => {
            if (mutation.type !== "attributes") return;
            const target = mutation.target;
            const attrName = mutation.attributeName || null;
            logJson("PARENT_LAYOUT_CHANGE", {
              timestamp: nowTs(),
              element: describeEl(target),
              attribute: attrName,
              oldValue: mutation.oldValue ?? null,
              newValue: target.getAttribute(attrName),
              cssText: target.style?.cssText || "",
              className: target.className || "",
            });
          });
        });
        parentObserver.observe(node, {
          attributes: true,
          attributeOldValue: true,
          attributeFilter: ["style", "class"],
        });
        observedParentNodes.add(node);
      }
      if (node === document.body) break;
      node = node.parentElement;
    }
  };
  const observeResizeTargets = () => {
    if (!resizeObserver) {
      resizeObserver = new ResizeObserver((entries) => {
        entries.forEach((entry) => {
          const target = entry.target;
          const nextWidth = Math.round(entry.contentRect.width);
          const nextHeight = Math.round(entry.contentRect.height);
          const prev = resizeState.get(target) || {
            width: null,
            height: null,
          };
          const recentWrite = getRecentWrite(target);
          logJson("RESIZE_TRACE", {
            timestamp: nowTs(),
            element: describeEl(target),
            width: nextWidth,
            height: nextHeight,
            oldWidth: prev.width,
            oldHeight: prev.height,
            stack: recentWrite?.stack || null,
            recentWriteProperty: recentWrite?.property || null,
            recentWriteValue: recentWrite?.newValue || null,
          });
          resizeState.set(target, {
            width: nextWidth,
            height: nextHeight,
          });
        });
      });
    }
    getTrackedNodes().forEach((node) => {
      if (!node || node.nodeType !== 1) return;
      try {
        resizeObserver.observe(node);
      } catch (e) {}
    });
  };
  const emitVisualViewportTrace = (reason) => {
    const vv = window.visualViewport;
    if (!vv) return;
    const next = {
      width: Math.round(vv.width || 0),
      height: Math.round(vv.height || 0),
      offsetTop: Math.round(vv.offsetTop || 0),
      pageTop: Math.round(vv.pageTop || 0),
      scale: Number(vv.scale || 0),
    };
    if (!visualViewportState) {
      visualViewportState = next;
      logJson("VISUAL_VIEWPORT_TRACE", {
        timestamp: nowTs(),
        reason,
        ...next,
      });
      return;
    }
    const changed = Object.keys(next).some((key) => {
      if (key === "scale") {
        return Math.abs(next[key] - visualViewportState[key]) >= 0.01;
      }
      return Math.abs(next[key] - visualViewportState[key]) >= 1;
    });
    if (!changed) return;
    logJson("VISUAL_VIEWPORT_TRACE", {
      timestamp: nowTs(),
      reason,
      ...next,
      oldWidth: visualViewportState.width,
      oldHeight: visualViewportState.height,
      oldOffsetTop: visualViewportState.offsetTop,
      oldPageTop: visualViewportState.pageTop,
      oldScale: visualViewportState.scale,
    });
    visualViewportState = next;
  };
  window.visualViewport?.addEventListener("resize", () =>
    emitVisualViewportTrace("resize"),
  );
  window.visualViewport?.addEventListener("scroll", () =>
    emitVisualViewportTrace("scroll"),
  );
  emitVisualViewportTrace("init");

  if (!window.__homeLayoutRuntimeAuditPatched) {
    window.__homeLayoutRuntimeAuditPatched = true;
    const styleProto = CSSStyleDeclaration.prototype;
    const originalSetProperty = styleProto.setProperty;
    styleProto.setProperty = function (name, value, priority) {
      const owner = findOwnerByStyle(this);
      if (owner && stylePropsToTrace.has(String(name))) {
        const stack = getStack();
        recordWrite(owner, {
          property: String(name),
          oldValue: this.getPropertyValue(name),
          newValue: value == null ? "" : String(value),
          stack,
        });
        logJson("LAYOUT_STYLE_WRITE", {
          timestamp: nowTs(),
          element: describeEl(owner),
          property: String(name),
          oldValue: this.getPropertyValue(name),
          newValue: value == null ? "" : String(value),
          cssText: owner.style.cssText || "",
          stack,
        });
      }
      return originalSetProperty.call(this, name, value, priority);
    };
    [
      "height",
      "minHeight",
      "maxHeight",
      "display",
      "transform",
      "scale",
      "flex",
      "flexGrow",
      "flexShrink",
      "gridTemplateRows",
      "padding",
      "paddingTop",
      "paddingRight",
      "paddingBottom",
      "paddingLeft",
      "margin",
      "marginTop",
      "marginRight",
      "marginBottom",
      "marginLeft",
    ].forEach((prop) => {
      const desc = Object.getOwnPropertyDescriptor(styleProto, prop);
      if (!desc?.set || !desc.get || desc.set.__homeLayoutAuditWrapped) return;
      const originalSetter = desc.set;
      const originalGetter = desc.get;
      const wrappedSetter = function (value) {
        const owner = findOwnerByStyle(this);
        if (owner) {
          const stack = getStack();
          recordWrite(owner, {
            property: prop,
            oldValue: originalGetter.call(this),
            newValue: value == null ? "" : String(value),
            stack,
          });
          logJson("LAYOUT_STYLE_WRITE", {
            timestamp: nowTs(),
            element: describeEl(owner),
            property: prop,
            oldValue: originalGetter.call(this),
            newValue: value == null ? "" : String(value),
            cssText: owner.style.cssText || "",
            stack,
          });
        }
        return originalSetter.call(this, value);
      };
      wrappedSetter.__homeLayoutAuditWrapped = true;
      Object.defineProperty(styleProto, prop, {
        configurable: desc.configurable,
        enumerable: desc.enumerable,
        get: originalGetter,
        set: wrappedSetter,
      });
    });
  }

  const scan = () => {
    observeResizeTargets();
    observeParentChain();
  };
  scan();
  bodyObserver = new MutationObserver(scan);
  bodyObserver.observe(document.body || document.documentElement, {
    childList: true,
    subtree: true,
  });
  window.__homeLayoutRuntimeAudit = {
    getTrackedNodes,
  };
}

if (document.body) {
  installHomeLayoutRuntimeAudit();
} else {
  window.addEventListener("DOMContentLoaded", installHomeLayoutRuntimeAudit, {
    once: true,
  });
}

function describeTraceTarget(target) {
  if (!target) return "unknown";
  const el = target.closest?.(
    "#fabBtn, #fabBtnSimple, .modal-close, .modal-overlay, .btn-primary, .btn-secondary, .nav-btn, .hero-chip, .balance-card-wide, .balance-row, #appLogoBtn",
  );
  if (!el) return null;
  return (
    el.id ||
    el.dataset?.tab ||
    el.dataset?.type ||
    el.className
      ?.toString()
      ?.split(" ")
      .filter(Boolean)
      .slice(0, 3)
      .join(".") ||
    el.tagName
  );
}

function rectSummary(el) {
  if (!el || !el.getBoundingClientRect) return null;
  const r = el.getBoundingClientRect();
  return {
    x: Math.round(r.x),
    y: Math.round(r.y),
    w: Math.round(r.width),
    h: Math.round(r.height),
  };
}

function elementState(id) {
  const el = document.getElementById(id);
  if (!el) return { exists: false };
  return {
    exists: true,
    parent:
      el.parentElement?.id || el.parentElement?.className?.toString?.() || null,
    display: el.style.display || "",
    visibility: el.style.visibility || "",
    opacity: el.style.opacity || "",
    rect: rectSummary(el),
  };
}

function traceLayoutSnapshot(reason) {
  if (!APP_TRACE_ENABLED) return;
  const mainContent = document.getElementById("mainContent");
  traceApp("layout-snapshot", {
    reason,
    tab: currentTab,
    simpleMode,
    mainContentChildren: mainContent?.children?.length ?? null,
    mainContentRect: rectSummary(mainContent),
    hero: elementState("heroCardWrap"),
    balance: elementState("balanceCard"),
    income: elementState("incomeCard"),
    expense: elementState("expenseCard"),
    salary: elementState("salaryCard"),
  });
}

function scheduleBootLayoutTracing() {
  if (!APP_TRACE_ENABLED) return;
  appBootTraceTimers.forEach((id) => clearTimeout(id));
  appBootTraceTimers = [];
  [0, 80, 180, 320, 600, 1000, 1600, 2400].forEach((delay) => {
    const timerId = setTimeout(
      () => traceLayoutSnapshot(`boot+${delay}ms`),
      delay,
    );
    appBootTraceTimers.push(timerId);
  });
}

function scheduleHomeRecoveryAfterAddCancel() {
  addModalRecoveryTimers.forEach((id) => clearTimeout(id));
  addModalRecoveryTimers = [];
  [60, 220, 520, 900].forEach((delay) => {
    const timerId = setTimeout(() => {
      if (document.getElementById("addModal")) return;
      if (currentTab !== "home" || simpleMode) return;
      // Раньше здесь вызывался renderHome() — четыре полных перерисовки главной
      // заново запускали анимацию графика и бюджета, из-за чего они накладывались
      // друг на друга. Если карточки на месте, достаточно вернуть им видимость;
      // renderHome — только если разметка главной действительно потеряна.
      const heroWrapEl = document.getElementById("heroCardWrap");
      const budgetHidden =
        !!heroWrapEl &&
        !!heroWrapEl.dataset &&
        heroWrapEl.dataset.budgetCard === "off";
      const heroIntact =
        !!heroWrapEl &&
        // Карточка бюджета выключена настройкой — её отсутствие не поломка.
        (budgetHidden || !!document.getElementById("ghBudgetCard"));
      if (heroIntact) {
        restoreHomeHeroIfNeeded();
      } else {
        renderHome();
      }
      updateTopBlocks();
    }, delay);
    addModalRecoveryTimers.push(timerId);
  });
}

function closeModal(id) {
  const m = document.getElementById(id);
  if (m) {
    if (m.classList.contains("closing")) return;
    if (id === "subcategoryPickerModal") m._pickerCleanup?.();
    traceApp("closeModal-start", {
      id,
      addModalCommitted,
      currentTab,
      simpleMode,
    });
    const shouldRestoreHomeAfterAddCancel =
      id === "addModal" &&
      !addModalCommitted &&
      currentTab === "home" &&
      !simpleMode;
    if (id === "addModal") {
      const sheet = m.querySelector(".add-modal-sheet");
      addModalLastClosedAt = Date.now();
      m.classList.remove("open");
      m.classList.add("closing");
      if (sheet) {
        sheet.classList.remove("dragging");
      }
      const duration = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ? 0 : 260;
      setTimeout(() => {
        m.style.display = "none";
        m.remove();
      }, duration);
      // Анимация графика и бюджета после закрытия окна — ровно один раз.
      // Раньше её запускали четыре восстановительных renderHome(), из-за чего
      // анимации накладывались друг на друга и дёргались.
      setTimeout(() => {
        if (currentTab !== "home" || simpleMode) return;
        // Если главная уже перерисовалась и анимация только что стартовала
        // (восстановление потерянной разметки), второй запуск не нужен.
        if (Date.now() - _heroAnimStartedAt < 250) return;
        playHomeHeroAnimations(true);
      }, duration + 40);
    } else {
      m.classList.remove("open");
      const compactWindow = ["fullHistoryModal", "subcategoryPickerModal", "subcategoryEditorModal"].includes(id);
      if (compactWindow) { m.classList.add("closing"); m.inert = true; m.setAttribute("aria-hidden", "true"); }
      // Окно бюджета закрывается переходом: класс .closing держит его на экране,
      // пока идут fade-out и scale(0.95), и лишь потом узел удаляется.
      const budgetWindow = id === "addBudgetModal";
      if (budgetWindow) { m.classList.add("closing"); m.inert = true; m.setAttribute("aria-hidden", "true"); }
      const reduceMotion = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
      const duration = compactWindow
        ? (reduceMotion ? 0 : 260)
        : budgetWindow
          ? (reduceMotion ? 0 : 300)
          : 350;
      setTimeout(() => m.remove(), duration);
    }
    const keepBodyLocked = !!document.querySelector(
      ".modal-overlay.open, .add-modal-host.open",
    );
    document.body.style.overflow = keepBodyLocked ? "hidden" : "";
    traceLayoutSnapshot(`closeModal:${id}`);
    updateHeroDebugOverlay();
    if (id === "addModal") addModalCommitted = false;
    setTimeout(() => ensureHomeHeroStable(), 20);
    if (shouldRestoreHomeAfterAddCancel) {
      traceApp("closeModal-recover-home", { id });
      scheduleHomeRecoveryAfterAddCancel();
    }
    scheduleGuideResume(`closeModal:${id}`, id === "addModal" ? 520 : 300);
  }
}

// ============================================================
// ИНИЦИАЛИЗАЦИЯ
// ============================================================
// Проверка пин-кода при запуске
// 🪙 Монеты при доходе (появляются ПОСЛЕ закрытия модалки, 1.5с)
function showCoinAnimation() {
  if (!animationsEnabled) return;
  const fab = document.getElementById("fabBtn");
  const cx = fab
    ? fab.getBoundingClientRect().left + 28
    : window.innerWidth / 2;
  const cy = fab ? fab.getBoundingClientRect().top : window.innerHeight * 0.8;
  for (let i = 0; i < 10; i++) {
    setTimeout(() => {
      const coin = document.createElement("div");
      coin.textContent = ["🪙", "💰", "✨", "💵"][
        Math.floor(Math.random() * 4)
      ];
      coin.style.cssText =
        `position:fixed;left:${cx}px;top:${cy}px;font-size:${24 + Math.random() * 16}px;` +
        `pointer-events:none;z-index:9999;filter:drop-shadow(0 2px 8px rgba(0,0,0,.25));`;
      document.body.appendChild(coin);
      const dx = (Math.random() - 0.5) * 200,
        dy = -(80 + Math.random() * 180);
      coin.animate(
        [
          { transform: "translate(-50%,-50%) scale(0)", opacity: 0 },
          {
            transform: `translate(calc(-50% + ${dx}px),calc(-50% + ${dy * 0.3}px)) scale(1.2)`,
            opacity: 1,
            offset: 0.3,
          },
          {
            transform: `translate(calc(-50% + ${dx}px),calc(-50% + ${dy}px)) scale(.4)`,
            opacity: 0,
          },
        ],
        {
          duration: 1300 + Math.random() * 300,
          easing: "cubic-bezier(0,.9,.57,1)",
          fill: "forwards",
        },
      );
      setTimeout(() => coin.remove(), 1700);
    }, i * 80);
  }
}

// 💸 Деньги при расходе (появляются ПОСЛЕ закрытия модалки, 1.5с)
function showMoneyFlyEffect() {
  if (!animationsEnabled) return;
  const emojis = ["💸", "💳", "🧾", "💴", "🏧", "💵"];
  for (let i = 0; i < 12; i++) {
    setTimeout(() => {
      const el = document.createElement("div");
      el.textContent = emojis[Math.floor(Math.random() * emojis.length)];
      const sx = window.innerWidth / 2 + (Math.random() - 0.5) * 160;
      el.style.cssText =
        `position:fixed;left:${sx}px;top:${window.innerHeight * 0.6}px;` +
        `font-size:${24 + Math.random() * 20}px;pointer-events:none;z-index:9999;` +
        `filter:drop-shadow(0 2px 8px rgba(0,0,0,.3));`;
      document.body.appendChild(el);
      const dx = (Math.random() - 0.5) * 300,
        dy = -(100 + Math.random() * 200),
        rot = (Math.random() - 0.5) * 540;
      el.animate(
        [
          { transform: "translate(0,0) scale(1) rotate(0deg)", opacity: 1 },
          {
            transform: `translate(${dx}px,${dy}px) scale(.15) rotate(${rot}deg)`,
            opacity: 0,
          },
        ],
        {
          duration: 1300 + Math.random() * 300,
          easing: "cubic-bezier(.2,.8,.4,1)",
          fill: "forwards",
        },
      );
      setTimeout(() => el.remove(), 1700);
    }, i * 70);
  }
}

// Stats auto-refresh
function startStatsAutoRefresh() {
  if (window._statsTimer) clearInterval(window._statsTimer);
  window._statsTimer = setInterval(() => {
    if (currentTab === "stats") {
      const sig =
        transactions.length +
        "," +
        transactions.reduce((s, tx) => s + tx.amountRub, 0).toFixed(0);
      if (sig !== window._lastSig) {
        window._lastSig = sig;
        renderStats();
      }
    }
  }, 2000);
}

function getIntervalMs(iv) {
  const map = {
    "1min": 1 * 60 * 1000,
    "5min": 5 * 60 * 1000,
    "10min": 10 * 60 * 1000,
    "15min": 15 * 60 * 1000,
    "30min": 30 * 60 * 1000,
    "1h": 60 * 60 * 1000,
    "2h": 2 * 60 * 60 * 1000,
    "5h": 5 * 60 * 60 * 1000,
    daily: 24 * 60 * 60 * 1000,
    every3days: 3 * 24 * 60 * 60 * 1000,
    weekly: 7 * 24 * 60 * 60 * 1000,
  };
  return map[iv] || 24 * 60 * 60 * 1000;
}

async function updateExchangeRates() {
  // Запасные курсы на случай офлайна
  const FALLBACK_RATES = {
    USD: 0.011,
    EUR: 0.01,
    GEL: 0.031,
    GBP: 0.0088,
    KZT: 5.12,
    RUB: 1,
  };
  try {
    const response = await fetch(
      "https://api.exchangerate.host/latest?base=RUB",
    );
    const data = await response.json();
    if (data.success && data.rates) {
      for (const c of ["USD", "EUR", "GEL", "GBP", "KZT"]) {
        if (data.rates[c]) {
          exchangeRates[c] = parseFloat(data.rates[c]);
        }
      }
      // Сохраняем актуальные курсы для офлайн-использования
      localStorage.setItem(
        "cachedRates",
        JSON.stringify({ rates: exchangeRates, ts: Date.now() }),
      );
      saveAll();
      refreshOperationViews();
      console.log("💱 Курсы валют обновлены");
    }
  } catch (e) {
    console.warn("⚠️ Ошибка обновления курсов:", e);
  }
}

function applyTimeBasedTheme() {
  // Only apply if user hasn't manually set a theme override
  if (localStorage.getItem("themeManualOverride")) return;
  const h = new Date().getHours();
  const shouldBeDark = h >= 19 || h < 7;
  const isDark = document.body.classList.contains("dark");
  if (shouldBeDark !== isDark) {
    applyColorTheme(shouldBeDark ? "dark" : "white");
    const tb = document.getElementById("themeToggle");
    if (tb) tb.textContent = shouldBeDark ? "☀️" : "🌙";
  }
}
// Check every 5 minutes
setInterval(applyTimeBasedTheme, 5 * 60 * 1000);

function startDeferredBackgroundServices() {
  if (backgroundServicesStarted) return;
  backgroundServicesStarted = true;

  setTimeout(() => {
    updateExchangeRates();
    setInterval(updateExchangeRates, 3600000);
  }, 1200);

  setTimeout(() => {
    startReminderPoller();
  }, 1800);

  setTimeout(() => {
    startRealtimeListener();
  }, 2200);

  setTimeout(() => {
    warmMessageCaches().catch(() => {});
  }, 3200);

  setTimeout(addVoiceButton, 1400);
  setTimeout(addGoalsNavButton, 1600);
  setTimeout(startDeferredUiEnhancements, 2200);
}

function startDeferredUiEnhancements() {
  if (deferredUiStarted) return;
  deferredUiStarted = true;

  setTimeout(() => {
    injectCardHelpButtons();
    injectNavHelpButtons();
    updateSupportBadge();
    setInterval(updateSupportBadge, 15000);
  }, 0);

  setTimeout(() => {
    ensureSupportButton();
  }, 200);

  setTimeout(() => {
    checkRecurringNotifications();
  }, 800);

  setTimeout(() => {
    if (shouldShowOnboarding()) showOnboarding();
  }, 1200);

  setTimeout(() => {
    showBudgetCelebration();
  }, 2200);
}

function convertTo12(time24) {
  if (!time24) return "";
  let [h, m] = time24.split(":");
  h = parseInt(h, 10);
  const ampm = h >= 12 ? "PM" : "AM";
  if (h > 12) h -= 12;
  if (h === 0) h = 12;
  return `${h}:${m} ${ampm}`;
}

function init() {
  appInitDone = true;
  applyTranslations();
  updateTopBlocks();
  forceHeroChipLayout();
  updateHeroDebugOverlay();
  traceApp("init", { currentLang, simpleMode, currentTab });
  updateHeader();
  addHeaderButtons();
  ensureSupportButton();
  document.documentElement.lang = currentLang;
  // Apply time-based theme before manual override check
  applyColorTheme(colorTheme || localStorage.getItem("colorTheme") || "dark");
  initLuxuryBackground();
  // After init, check time-based theme (respects existing setting)
  setTimeout(applyTimeBasedTheme, 200);
  applyFontSize(fontSize || "normal");
  applySimpleMode(simpleMode || localStorage.getItem("simpleMode") === "true");
  forceHeroChipLayout();
  updateHeroDebugOverlay();
  attachAppTraceObservers();
  const tb = document.getElementById("themeToggle");
  if (tb)
    tb.textContent = document.body.classList.contains("dark") ? "☀️" : "🌙";
  // ── HAPTIC EVERYWHERE ──
  document.querySelectorAll(".nav-btn").forEach((btn) => {
    btn.addEventListener("click", () => haptic("light"), { passive: true });
  });
  // Делегирование событий — работает с динамически рендеренными chips
  document.addEventListener("click", (e) => {
    const traceTarget = describeTraceTarget(e.target);
    if (traceTarget) traceApp("click", { target: traceTarget });
    const card = e.target.closest(
      ".summary-card, .hero-chip, .balance-card-wide, .gh-budget",
    );
    if (!card) return;
    haptic("light");
    const type = card.dataset.type;
    if (type === "salary") {
      openSalaryModal();
      return;
    }
    if (type === "budget") {
      // Свайп карусели и тап по точке пагинации не должны открывать окно:
      // после реального сдвига пальца клик гасится на 220 мс.
      if (Date.now() < _budgetCarouselTapGuardUntil) return;
      // Слайд 0 — общий обзор: окно открывается на начале списка всех лимитов и
      // подсвечивает все карточки сразу. Слайды 1…N — конкретный лимит: окно
      // прокручивается к его карточке и подсвечивает только её.
      openAddBudgetModal(getBudgetTapFocusOptions(e.target));
      return;
    }
    if (type === "income" || type === "expense") {
      // Повторное нажатие по той же карточке снимает фильтр (и по типу, и по
      // периоду), чтобы история вернулась в исходное состояние.
      // Возвращённое значение — состояние currentFilter после переключения:
      // тип при применении фильтра и null при отмене.
      const activeFilter = toggleHistoryFilter(type, card.dataset.period);
      if (simpleMode) {
        // В упрощённом режиме — обновляем список и прокручиваем
        // Задержка — на перерисовку: высота списка после фильтра другая,
        // поэтому цель прокрутки считаем уже по новому DOM.
        refreshHomeList();
        setTimeout(() => {
          // Скролл к истории нужен только когда фильтр применён. При отмене
          // пользователь остаётся на том же месте экрана, где нажал карточку.
          if (activeFilter) scrollHistoryToTop();
          showToast(
            currentFilter === null ? t("cancel") : type === "income"
              ? t("toastIncomeFilter")
              : t("toastExpenseFilter"),
            "success",
          );
        }, 120);
      } else {
        if (currentTab !== "home") setTab("home");
        else {
          renderOpsList();
        }
        setTimeout(() => {
          // Как и в упрощённом режиме: снятие фильтра не двигает экран.
          if (activeFilter) scrollHistoryToTop();
          showToast(
            currentFilter === null
              ? t("cancel")
              : type === "income"
                ? t("toastIncomeFilter")
                : t("toastExpenseFilter"),
            "success",
          );
        }, 200);
      }
    } else {
      // Карточка «Баланс»: всегда возвращает историю к исходному состоянию.
      const hadFilter =
        currentFilter !== null || (historyFilter && historyFilter !== "allTime");
      resetHistoryFilter();
      if (currentTab !== "home") setTab("home");
      else if (hadFilter) {
        if (simpleMode) refreshHomeList();
        else renderOpsList();
        showToast(t("cancel"), "success");
      }
    }
  });
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Enter" && e.key !== " ") return;
    const card = e.target.closest(
      ".summary-card, .hero-chip, .balance-card-wide",
    );
    if (card) card.click();
  });
  bindTapSafeAction(document.getElementById("fabBtn"), (e) => {
    if (isVoiceDragSuppressed()) {
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    openAddModal("expense");
  });
  // ── Инициализация push-уведомлений ──

  setTab("home", () => {
    appBooting = false;
    // Первая отрисовка главной = appReady: только теперь снимаем сплэш.
    hideBootSplash();
    // Сплэш уходит с плавным затуханием (~200 мс). Анимацию бюджета
    // перезапускаем уже после него: иначе при первом входе она целиком
    // проигрывает под сплэшем, и пользователь видит только готовый процент.
    if (typeof setTimeout === "function")
      setTimeout(() => {
        if (currentTab !== "home" || simpleMode) return;
        if (typeof playHomeHeroAnimations === "function")
          playHomeHeroAnimations(true);
      }, 220);
    startDeferredBackgroundServices();
    ensureHeroWrapGuard();
    setTimeout(() => ensureHomeHeroStable(8, 150), 120);
  });

  // ── Обработчики обеих навигаций ──
  const fabBtnSimple = document.getElementById("fabBtnSimple");
  if (fabBtnSimple)
    bindTapSafeAction(fabBtnSimple, (e) => {
      if (isVoiceDragSuppressed()) {
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      openAddModal("expense");
    });

  // Все кнопки с data-tab в обоих навах
  document
    .querySelectorAll(
      "#mainNav .nav-btn[data-tab], #simpleNav .nav-btn[data-tab]",
    )
    .forEach((btn) => {
      btn.addEventListener("click", () => setTab(btn.dataset.tab));
    });

  // ── Шторка "Ещё" ──
  function openMoreDrawer() {
    const drawer = document.getElementById("moreDrawer");
    if (!drawer) return;
    drawer.style.display = "block";
    // Локализация пунктов
    const labels = {
      tools: t("tools"),
      settings: t("settings"),
      notebook: t("notebook"),
    };
    drawer.querySelectorAll("[data-i18n-more]").forEach((el) => {
      const key = el.dataset.i18nMore;
      if (labels[key]) el.textContent = labels[key];
    });
    // Клики по пунктам меню
    drawer.querySelectorAll(".more-item[data-tab]").forEach((btn) => {
      btn.onclick = () => {
        closeMoreDrawer();
        setTab(btn.dataset.tab);
      };
    });
    document.getElementById("moreShareBtn")?.addEventListener("click", () => {
      closeMoreDrawer();
      const activeProf =
        profiles.find((p) => p.id === activeProfileId) || profiles[0];
      if (activeProf && typeof openShareModal === "function")
        openShareModal(activeProf);
      else showToast(t("profileNotFound"), "error");
    });
    // Закрытие по оверлею и свайпу вниз
    const overlay = document.getElementById("moreDrawerOverlay");
    overlay && (overlay.onclick = closeMoreDrawer);
    // Свайп вниз для закрытия
    const sheet = drawer.querySelector(".more-sheet");
    let startY = 0;
    sheet?.addEventListener(
      "touchstart",
      (e) => {
        startY = e.touches[0].clientY;
      },
      { passive: true },
    );
    sheet?.addEventListener(
      "touchend",
      (e) => {
        if (e.changedTouches[0].clientY - startY > 60) closeMoreDrawer();
      },
      { passive: true },
    );
  }
  function closeMoreDrawer() {
    const drawer = document.getElementById("moreDrawer");
    if (drawer) {
      const sheet = drawer.querySelector(".more-sheet");
      if (sheet) {
        sheet.style.animation = "none";
        sheet.style.transform = "translateY(100%)";
        sheet.style.transition = "transform .25s ease";
      }
      setTimeout(() => {
        if (drawer) drawer.style.display = "none";
        if (sheet) {
          sheet.style.transform = "";
          sheet.style.transition = "";
          sheet.style.animation = "";
        }
      }, 240);
    }
  }
  window.openMoreDrawer = openMoreDrawer;
  window.closeMoreDrawer = closeMoreDrawer;

  document
    .getElementById("moreNavBtn")
    ?.addEventListener("click", openMoreDrawer);
  document
    .getElementById("moreNavBtnSimple")
    ?.addEventListener("click", openMoreDrawer);
  document
    .getElementById("settingsNavBtnSimple")
    ?.addEventListener("click", () => setTab("settings"));

  // ── Graphite Neon: иконки шапки (уведомления и меню) ──
  const ghBellBtn = document.getElementById("ghBellBtn");
  if (ghBellBtn && !ghBellBtn.dataset.ghBound) {
    ghBellBtn.dataset.ghBound = "1";
    ghBellBtn.addEventListener("click", () => {
      setTab("settings");
      if (typeof openSettingsNotifications === "function") {
        openSettingsNotifications();
      }
    });
  }
  const ghMenuBtn = document.getElementById("ghMenuBtn");
  if (ghMenuBtn && !ghMenuBtn.dataset.ghBound) {
    ghMenuBtn.dataset.ghBound = "1";
    ghMenuBtn.addEventListener("click", openMoreDrawer);
  }

  // ==== ПРОВЕРКА ФЛАГА НОВЫХ СООБЩЕНИЙ ПРИ ЗАГРУЗКЕ ====
  const checkSupportFlag = () => {
    if (
      localStorage.getItem("has_new_support_messages") === "true" &&
      isCreator()
    ) {
      setTimeout(() => {
        showToast("📬 " + t("newUserMessages"), "success", 3000);
        localStorage.removeItem("has_new_support_messages");
      }, 300);
    }
  };
  checkSupportFlag();
  window.addEventListener("pageshow", checkSupportFlag);

  // Обработчики удаления в настройках (делегирование)
  document.getElementById("mainContent").addEventListener("click", (e) => {
    if (e.target.classList.contains("budget-del-btn")) {
      const cat = e.target.dataset.cat;
      askConfirm(
        t("budgetDeleteConfirm"),
        () => {
          delete categoryBudgets[cat];
          saveAll();
          renderSettings();
        },
        { icon: "🗑️" },
      );
    } else if (e.target.classList.contains("rec-del-btn")) {
      const i = parseInt(e.target.dataset.idx);
      askConfirm(
        t("recurringDeleteConfirm"),
        () => {
          recurringOps.splice(i, 1);
          saveAll();
          renderSettings();
        },
        { icon: "🗑️" },
      );
    } else if (e.target.hasAttribute("data-deletepid")) {
      const pid = e.target.getAttribute("data-deletepid");
      const prof = profiles.find((p) => p.id === pid);
      if (!prof) return;
      askConfirm(
        t("profileDeleteConfirm"),
        () => {
          // Если удаляем активный профиль, переключаемся на другой
          if (pid === activeProfileId) {
            const other = profiles.find((p) => p.id !== pid);
            if (other) {
              switchProfile(other.id);
            } else {
              // Если других нет — создаём дефолтный профиль
              const defaultProf = {
                id: "default",
                name: "Main profile",
                emoji: "👤",
                color: "#2d6a4f",
              };
              profiles = [defaultProf];
              activeProfileId = "default";
              saveGlobal();
              loadProfileData("default");
              syncStartBalanceTransaction();
              setTab("home");
            }
          }
          // Удаляем данные профиля из localStorage
          localStorage.removeItem(getProfileStorageKey(pid));
          profiles = profiles.filter((p) => p.id !== pid);
          saveGlobal();
          renderSettings();
          showToast(t("deleted"));
        },
        { icon: "🗑️" },
      );
    }
  });
  // Проверка новых сообщений при возвращении на вкладку
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) {
      restartRealtimeListener().catch(() => {});
    }
    if (
      !document.hidden &&
      isCreator() &&
      localStorage.getItem("has_new_support_messages") === "true"
    ) {
      setTimeout(() => {
        showToast("📬 " + t("newUserMessages"), "success", 3000);
        localStorage.removeItem("has_new_support_messages");
      }, 300);
    }
  });
}

