    hundred: 100,
    ერთი: 1,
    ორი: 2,
    სამი: 3,
    ოთხი: 4,
    ხუთი: 5,
    ექვსი: 6,
    შვიდი: 7,
    რვა: 8,
    ცხრა: 9,
    ათი: 10,
    თერთმეტი: 11,
